// FIXED template (deterministic, no AI). Booking-triggered upgrade pitch with
// the tiered offer + 7-day guarantee. Builds the tap-to-send wa.me link.
let e = $('Get Engagement').item.json; if (Array.isArray(e)) e = e[0]; e = e || {};
let p = $('Get Prospect').item.json; if (Array.isArray(p)) p = p[0] || {};
let supp = $('Check Suppression').item.json; if (!Array.isArray(supp)) supp = supp ? [supp] : [];

const who = (e.owner_first_name && e.owner_first_name.trim()) ? e.owner_first_name.trim() : '';
const biz = e.business_name || 'your salon';
const hasDetail = e.latest_customer_first_name && e.latest_service_name;
function waDigits(raw){ let d = String(raw||'').replace(/\D/g,''); if (d.startsWith('0')) d = '27' + d.slice(1); if (d.length === 9) d = '27' + d; return d; }
const phone = waDigits(p.whatsapp_e164 || p.phone_e164 || '');
const suppressed = supp.length > 0 || p.popia_optout === true;

const bookingLine = hasDetail
  ? biz + ' just took a booking off the free page — ' + e.latest_customer_first_name + ' for ' + e.latest_service_name + (e.latest_booking_date_human ? ' on ' + e.latest_booking_date_human : '') + '. That\'s the whole idea.'
  : biz + ' just took a booking straight off the free page I set up. That\'s the whole idea.';

const text = [
  (who ? who + ', quick one.' : 'Quick one.'),
  '',
  bookingLine,
  '',
  'That\'s the free version working. Here\'s what the paid setup adds:',
  '',
  'Booking Booster — from R2,500 once-off or R699/mo: keep the free page plus deposits, auto WhatsApp reminders, your own domain, and Streamline branding removed.',
  '',
  'Client Magnet (most popular) — from R12,000 + R1,199/mo: pro site and booking system with deposits, reminders, your own domain and lead capture. Live in a week.',
  '',
  'Business Accelerator — R25,000 + R2,499/mo: full site and store, automated bookings, deposits, reminders, customer database, rebooking, analytics, and monthly improvement.',
  '',
  'My guarantee: your upgraded booking system — deposits, reminders, your own domain — is live and taking real bookings within 7 days, or I keep working free until it is. I guarantee the system works; your bookings are your magic.',
  '',
  'Want a quick 15-min chat to map it out?',
  '',
  '— Christiaan from Streamline'
].join('\n');

const waLink = (!suppressed && phone) ? ('https://wa.me/' + phone + '?text=' + encodeURIComponent(text)) : '';
const summary = suppressed
  ? ('🔥 ' + biz + ' booked, but it\'s on the suppression list / opted out — NOT generating an upgrade link.')
  : ['🔥 BOOKING-TRIGGERED upgrade ready for ' + biz + (phone ? ' (+' + phone + ')' : ' (NO PHONE)'), '', 'Tap to send the upgrade pitch:', '', text].join('\n');

return [{ json: { prospect_id: e.prospect_id, business_name: biz, draft_text: text, waLink, summary, suppressed, phone } }];
